		fr: "Lisse la trajectoire de la caméra et zoome légèrement pour masquer les bords.",
		hi: "कैमरा पथ को स्मूद करता है और किनारे छिपाने के लिए थोड़ा ज़ूम करता है।",
		it: "Ammorbidisce il percorso della camera e ingrandisce leggermente per nascondere i bordi.",
