	"Place this clip right after another clip on its track to add a transition.":
		{
			ar: "ضع هذا المقطع مباشرة بعد مقطع آخر على مساره لإضافة انتقال.",
			de: "Platzieren Sie diesen Clip direkt nach einem anderen Clip auf seiner Spur, um einen Übergang hinzuzufügen.",
			es: "Coloca este clip justo después de otro clip en su pista para añadir una transición.",
			fr: "Placez ce clip juste après un autre clip sur sa piste pour ajouter une transition.",
			hi: "ट्रांज़िशन जोड़ने के लिए इस क्लिप को उसके ट्रैक पर किसी दूसरी क्लिप के ठीक बाद रखें।",
			it: "Posiziona questa clip subito dopo un'altra clip sulla sua traccia per aggiungere una transizione.",
			ja: "トランジションを追加するには、このクリップを同じトラック上の別のクリップの直後に置いてください。",
			ko: "전환을 추가하려면 이 클립을 같은 트랙의 다른 클립 바로 뒤에 두세요.",
			"pt-BR":
				"Coloque este clipe logo após outro clipe na mesma faixa para adicionar uma transição.",
			ru: "Чтобы добавить переход, поставьте клип сразу после другого клипа на его дорожке.",
			"zh-CN": "将此片段紧接在同一轨道的另一片段之后即可添加转场。",
		},
	"Pick a transition for the cut into this clip. The clip extends under the previous one so the program length stays the same.":
		{
			ar: "اختر انتقالًا للقطع الداخل إلى هذا المقطع. يمتد المقطع تحت المقطع السابق لتبقى مدة البرنامج كما هي.",
			de: "Wählen Sie einen Übergang für den Schnitt in diesen Clip. Der Clip verlängert sich unter den vorherigen, sodass die Programmlänge gleich bleibt.",
			es: "Elige una transición para el corte hacia este clip. El clip se extiende bajo el anterior para que la duración del programa no cambie.",
			fr: "Choisissez une transition pour la coupe vers ce clip. Le clip se prolonge sous le précédent pour que la durée du programme reste la même.",
			hi: "इस क्लिप में आने वाले कट के लिए ट्रांज़िशन चुनें। क्लिप पिछली क्लिप के नीचे तक बढ़ती है, ताकि प्रोग्राम की लंबाई वही रहे।",
			it: "Scegli una transizione per lo stacco verso questa clip. La clip si estende sotto la precedente così la durata del programma resta invariata.",
			ja: "このクリップへのカットのトランジションを選びます。クリップは前のクリップの下まで延長されるため、全体の長さは変わりません。",
			ko: "이 클립으로 들어오는 컷의 전환을 고르세요. 클립이 이전 클립 아래로 늘어나 전체 길이는 그대로 유지됩니다.",
			"pt-BR":
				"Escolha uma transição para o corte para este clipe. O clipe se estende sob o anterior para que a duração do programa não mude.",
			ru: "Выберите переход для склейки в этот клип. Клип продлевается под предыдущим, поэтому длина программы не меняется.",
			"zh-CN":
				"为切入此片段的剪辑点选择转场。片段会延伸到前一片段下方，节目总长度保持不变。",
		},
