			fr: "Transformez les meilleurs moments de ce projet en projets courts distincts : recadrés pour le nouveau format, sous-titrés mot à mot, avec un préréglage de publication adapté.",
			hi: "इस प्रोजेक्ट की सबसे अच्छी झलकियों को अलग-अलग छोटे प्रोजेक्ट में बदलें: नए आस्पेक्ट के लिए रीफ़्रेम, एक-एक शब्द के कैप्शन और मिलते-जुलते पब्लिश प्रीसेट के साथ।",
			it: "Trasforma i momenti migliori di questo progetto in progetti brevi separati: reinquadrati per il nuovo formato, sottotitolati una parola alla volta, con un preset di pubblicazione adatto.",
			ja: "このプロジェクトのハイライトを個別のショートプロジェクトにします。新しいアスペクト比にリフレームし、1 単語ずつ字幕を付け、対応する公開プリセットを設定します。",
			ko: "이 프로젝트의 하이라이트를 별도 쇼츠 프로젝트로 만듭니다. 새 화면비에 맞게 리프레임하고 한 단어씩 자막을 달며 알맞은 게시 프리셋을 적용합니다.",
