	"List words the transcription gets wrong and how to spell them. Fixing replaces every whole-word match, ignoring case, in the captions and the source transcripts in one undoable step.":
		{
			ar: "اذكر الكلمات التي يخطئ فيها التفريغ وكيف تُكتب. يستبدل التصحيح كل تطابق لكلمة كاملة، دون مراعاة حالة الأحرف، في التسميات ونصوص المصدر بخطوة واحدة قابلة للتراجع.",
			de: "Listen Sie Wörter auf, die die Transkription falsch erkennt, und wie sie geschrieben werden. Die Korrektur ersetzt jede Ganzwort-Übereinstimmung ohne Beachtung der Groß-/Kleinschreibung in Untertiteln und Quelltranskripten in einem rückgängig machbaren Schritt.",
			es: "Enumera las palabras que la transcripción escribe mal y cómo se escriben. Corregir sustituye cada coincidencia de palabra completa, sin distinguir mayúsculas, en los subtítulos y las transcripciones de origen en un solo paso que se puede deshacer.",
			fr: "Listez les mots que la transcription comprend mal et leur orthographe. La correction remplace chaque occurrence du mot entier, sans tenir compte de la casse, dans les sous-titres et les transcriptions sources, en une seule étape annulable.",
			hi: "वे शब्द लिखें जिन्हें ट्रांसक्रिप्शन ग़लत लिखता है और उनकी सही वर्तनी बताएँ। सुधार कैप्शन और स्रोत ट्रांसक्रिप्ट में हर पूरे शब्द के मिलान को, केस अनदेखा करते हुए, एक ही पूर्ववत होने वाले चरण में बदल देता है।",
			it: "Elenca le parole che la trascrizione sbaglia e come si scrivono. La correzione sostituisce ogni corrispondenza della parola intera, senza distinzione tra maiuscole e minuscole, nei sottotitoli e nelle trascrizioni sorgente in un unico passaggio annullabile.",
			ja: "文字起こしが間違える単語と正しい表記を一覧にします。修正すると、字幕とソースの文字起こし内の単語全体の一致（大文字小文字は区別しない）を、元に戻せる 1 回の操作ですべて置き換えます。",
			ko: "전사가 잘못 적는 단어와 올바른 철자를 적으세요. 수정하면 자막과 소스 전사본에서 대소문자 구분 없이 단어 전체가 일치하는 모든 항목을 되돌릴 수 있는 한 단계로 바꿉니다.",
			"pt-BR":
				"Liste as palavras que a transcrição erra e como escrevê-las. A correção substitui cada ocorrência da palavra inteira, sem diferenciar maiúsculas, nas legendas e nas transcrições de origem em uma única etapa que pode ser desfeita.",
			ru: "Перечислите слова, которые расшифровка распознаёт неверно, и как их писать. Исправление заменяет каждое совпадение целого слова без учёта регистра в субтитрах и исходных расшифровках за один отменяемый шаг.",
			"zh-CN":
				"列出转录出错的词及其正确写法。修正会在一个可撤销的步骤中，不区分大小写地替换字幕和源转录稿中所有整词匹配项。",
		},
