	"Resolutions scale the timeline's short side and keep its aspect. A custom size with a different aspect is letterboxed.":
		{
			ar: "تغيّر الدقات الضلع الأقصر للخط الزمني وتحافظ على نسبة أبعاده. يُضاف إلى الحجم المخصص بنسبة أبعاد مختلفة أشرطة سوداء.",
			de: "Auflösungen skalieren die kurze Seite der Timeline und behalten ihr Seitenverhältnis bei. Eine eigene Größe mit anderem Seitenverhältnis erhält schwarze Balken.",
			es: "Las resoluciones escalan el lado corto de la línea de tiempo y mantienen su relación de aspecto. Un tamaño personalizado con otra relación de aspecto se exporta con bandas negras.",
			fr: "Les résolutions mettent à l'échelle le petit côté de la timeline et conservent son format. Une taille personnalisée d'un autre format est complétée par des bandes noires.",
			hi: "रिज़ॉल्यूशन टाइमलाइन की छोटी भुजा को स्केल करते हैं और उसका आस्पेक्ट बनाए रखते हैं। अलग आस्पेक्ट वाले कस्टम आकार पर लेटरबॉक्स जोड़ा जाता है।",
			it: "Le risoluzioni scalano il lato corto della timeline e ne mantengono le proporzioni. Una dimensione personalizzata con proporzioni diverse riceve bande nere.",
			ja: "解像度はタイムラインの短辺を拡大縮小し、アスペクト比を保ちます。アスペクト比が異なるカスタムサイズはレターボックスになります。",
			ko: "해상도는 타임라인의 짧은 변을 조정하고 화면비를 유지합니다. 화면비가 다른 사용자 지정 크기에는 레터박스가 적용됩니다.",
			"pt-BR":
				"As resoluções ajustam o lado menor da linha do tempo e mantêm a proporção. Um tamanho personalizado com outra proporção recebe barras pretas.",
			ru: "Разрешения масштабируют короткую сторону таймлайна и сохраняют её соотношение сторон. К своему размеру с другим соотношением добавляются поля.",
			"zh-CN":
				"分辨率会缩放时间线的短边并保持其画面比例。比例不同的自定义尺寸会添加黑边。",
		},
