	"Ryu has not granted Video Studio screen or camera capture in this view. Record with another app and import the file from Media.":
		{
			ar: "لم يمنح Ryu تطبيق Video Studio إذن التقاط الشاشة أو الكاميرا في هذا العرض. سجّل بتطبيق آخر واستورد الملف من الوسائط.",
			de: "Ryu hat Video Studio in dieser Ansicht keine Bildschirm- oder Kameraaufnahme erlaubt. Nehmen Sie mit einer anderen App auf und importieren Sie die Datei unter Medien.",
			es: "Ryu no ha concedido a Video Studio la captura de pantalla o cámara en esta vista. Graba con otra app e importa el archivo desde Medios.",
			fr: "Ryu n'a pas autorisé Video Studio à capturer l'écran ou la caméra dans cette vue. Enregistrez avec une autre app et importez le fichier depuis Médias.",
			hi: "Ryu ने इस व्यू में Video Studio को स्क्रीन या कैमरा कैप्चर की अनुमति नहीं दी है। किसी दूसरे ऐप से रिकॉर्ड करें और फ़ाइल को मीडिया से इंपोर्ट करें।",
			it: "Ryu non ha concesso a Video Studio la cattura di schermo o fotocamera in questa vista. Registra con un'altra app e importa il file da Media.",
			ja: "このビューでは Ryu が Video Studio に画面やカメラの取り込みを許可していません。別のアプリで録画し、メディアからファイルを読み込んでください。",
			ko: "이 보기에서는 Ryu가 Video Studio에 화면 또는 카메라 캡처를 허용하지 않았습니다. 다른 앱으로 녹화한 뒤 미디어에서 파일을 가져오세요.",
			"pt-BR":
				"O Ryu não concedeu ao Video Studio captura de tela ou câmera nesta visualização. Grave com outro app e importe o arquivo em Mídia.",
			ru: "Ryu не разрешил Video Studio захват экрана или камеры в этом представлении. Запишите в другом приложении и импортируйте файл в разделе «Медиа».",
			"zh-CN":
				"Ryu 未在此视图中授予 Video Studio 屏幕或摄像头捕获权限。请用其他应用录制，再从“媒体”导入文件。",
		},
