	"Region on the canvas at the playhead, in percent of the frame. Drag the dashed box on the preview to move it, or draw a new one. The subject is tracked from the playhead to the end of the clip.":
		{
			ar: "المنطقة على اللوحة عند رأس التشغيل، بنسبة مئوية من الإطار. اسحب المربع المتقطع على المعاينة لنقله أو ارسم مربعًا جديدًا. يُتتبع الموضوع من رأس التشغيل حتى نهاية المقطع.",
			de: "Bereich auf der Leinwand am Abspielkopf in Prozent des Bildes. Ziehen Sie den gestrichelten Rahmen in der Vorschau, um ihn zu verschieben, oder zeichnen Sie einen neuen. Das Motiv wird vom Abspielkopf bis zum Clipende verfolgt.",
			es: "Región del lienzo en el cabezal, en porcentaje del fotograma. Arrastra el cuadro discontinuo en la vista previa para moverlo o dibuja uno nuevo. El sujeto se sigue desde el cabezal hasta el final del clip.",
			fr: "Zone du canevas à la tête de lecture, en pourcentage de l'image. Faites glisser le cadre en pointillés dans l'aperçu pour la déplacer, ou dessinez-en un nouveau. Le sujet est suivi de la tête de lecture jusqu'à la fin du clip.",
			hi: "प्लेहेड पर कैनवस का क्षेत्र, फ़्रेम के प्रतिशत में। उसे हिलाने के लिए प्रीव्यू पर डैश वाला बॉक्स खींचें या नया बनाएँ। विषय को प्लेहेड से क्लिप के अंत तक ट्रैक किया जाता है।",
			it: "Regione dell'area di lavoro alla testina, in percentuale del fotogramma. Trascina il riquadro tratteggiato nell'anteprima per spostarlo o disegnane uno nuovo. Il soggetto viene tracciato dalla testina alla fine della clip.",
			ja: "再生ヘッド位置のキャンバス上の領域（フレームに対する %）。プレビュー上の破線の枠をドラッグして移動するか、新しく描画します。被写体は再生ヘッドからクリップの終わりまで追跡されます。",
			ko: "재생 헤드 위치의 캔버스 영역(프레임 대비 %). 미리보기에서 점선 상자를 끌어 옮기거나 새로 그리세요. 피사체는 재생 헤드부터 클립 끝까지 추적됩니다.",
			"pt-BR":
				"Região na tela no cabeçote, em porcentagem do quadro. Arraste a caixa tracejada na prévia para movê-la ou desenhe uma nova. O objeto é rastreado do cabeçote até o fim do clipe.",
			ru: "Область холста у указателя в процентах от кадра. Перетащите пунктирную рамку в предпросмотре или нарисуйте новую. Объект отслеживается от указателя до конца клипа.",
			"zh-CN":
				"播放头处画布上的区域（以画面百分比表示）。在预览上拖动虚线框可移动它，或绘制新的区域。将从播放头跟踪主体直到片段结束。",
		},
