			fr: "Appuyez sur ? pour voir et modifier tous les raccourcis clavier. Rouvrez cette visite à tout moment avec Faire la visite.",
			hi: "हर कीबोर्ड शॉर्टकट देखने और बदलने के लिए ? दबाएँ। टूर लें से यह टूर कभी भी फिर खोलें।",
